class ProfitMenteBundleEngine{
  sanitize(name){return String(name||'asset').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-120)}
  oct(n,len){return n.toString(8).padStart(len-1,'0')+'\0'}
  header(name,size){const h=new Uint8Array(512),enc=new TextEncoder(),put=(s,o,l)=>h.set(enc.encode(s).slice(0,l),o);put(name,0,100);put('0000777\0',100,8);put('0000000\0',108,8);put('0000000\0',116,8);put(this.oct(size,12),124,12);put(this.oct(Math.floor(Date.now()/1000),12),136,12);for(let i=148;i<156;i++)h[i]=32;h[156]='0'.charCodeAt(0);put('ustar\0',257,6);put('00',263,2);let sum=h.reduce((a,b)=>a+b,0);put(sum.toString(8).padStart(6,'0')+'\0 ',148,8);return h}
  async build(project,assets){const enc=new TextEncoder(),parts=[],manifest=structuredClone(project);manifest.version='1.6';manifest.assets=[];for(const a of assets){const filename=`${a.id.slice(0,8)}-${this.sanitize(a.name)}`,path=`assets/${filename}`,bytes=new Uint8Array(await a.blob.arrayBuffer());parts.push(this.header(path,bytes.length),bytes,new Uint8Array((512-bytes.length%512)%512));manifest.assets.push({id:a.id,name:filename,type:a.type,mime:a.mime||''})}const json=enc.encode(JSON.stringify(manifest,null,2));parts.unshift(this.header('project.json',json.length),json,new Uint8Array((512-json.length%512)%512));parts.push(new Uint8Array(1024));return new Blob(parts,{type:'application/x-tar'})}
  async download(project,assets){const blob=await this.build(project,assets),a=document.createElement('a'),safe=this.sanitize(project.name||'profitmente');a.href=URL.createObjectURL(blob);a.download=`${safe}.profitmente.tar`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return blob.size}
  async health(){try{const r=await fetch('/api/health',{cache:'no-store'});if(!r.ok)return {ok:false,render_ready:false};return await r.json()}catch{return {ok:false,render_ready:false}}}
  async renderLocal(project,assets,onStatus=()=>{}){const health=await this.health();if(!health.ok)throw new Error('Abre Studio con start_studio_windows.bat para activar el render MP4 directo.');if(!health.render_ready)throw new Error('FFmpeg y FFprobe no están disponibles. Instala FFmpeg gratis y vuelve a abrir Studio.');onStatus('Empaquetando proyecto y medios…');const blob=await this.build(project,assets);onStatus(`Enviando ${(blob.size/1048576).toFixed(1)} MB al render local…`);const r=await fetch('/api/render',{method:'POST',headers:{'Content-Type':'application/x-tar'},body:blob});if(!r.ok){let msg=`Error HTTP ${r.status}`;try{const data=await r.json();msg=data.error||msg}catch{}throw new Error(msg)}onStatus('MP4 terminado. Preparando descarga…');const mp4=await r.blob(),a=document.createElement('a'),safe=this.sanitize(project.name||'profitmente');a.href=URL.createObjectURL(mp4);a.download=`${safe}.mp4`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);return mp4.size}
  readString(bytes,start,len){return new TextDecoder().decode(bytes.slice(start,start+len)).replace(/\0.*$/s,'').trim()}
  async parse(blob){const bytes=new Uint8Array(await blob.arrayBuffer()),files=new Map();let offset=0;while(offset+512<=bytes.length){const header=bytes.slice(offset,offset+512);if(header.every(x=>x===0))break;const name=this.readString(header,0,100),sizeRaw=this.readString(header,124,12),size=parseInt(sizeRaw||'0',8);if(!name||!Number.isFinite(size)||size<0)throw new Error('Paquete TAR inválido');offset+=512;if(offset+size>bytes.length)throw new Error('Paquete TAR truncado');files.set(name,bytes.slice(offset,offset+size));offset+=Math.ceil(size/512)*512}const projectBytes=files.get('project.json');if(!projectBytes)throw new Error('El paquete no contiene project.json');let project;try{project=JSON.parse(new TextDecoder().decode(projectBytes))}catch{throw new Error('project.json inválido')}if(!Array.isArray(project.clips))throw new Error('Proyecto sin clips válidos');const restored=[];for(const meta of project.assets||[]){const path=`assets/${meta.name}`,data=files.get(path);if(!data)throw new Error(`Medio faltante en paquete: ${meta.name}`);const prefix=`${String(meta.id||'').slice(0,8)}-`,stored=String(meta.name||''),originalName=stored.startsWith(prefix)?stored.slice(prefix.length):stored;restored.push({id:meta.id,name:originalName,type:meta.type,mime:meta.mime||'',blob:new Blob([data],{type:meta.mime||'application/octet-stream'})})}project.assets=(project.assets||[]).map(({id,name,type,mime})=>({id,name,type,mime}));return {project,assets:restored}}
  async showReadiness(){if(typeof document==='undefined')return;let badge=document.querySelector('#renderStatus');if(!badge){badge=document.createElement('span');badge.id='renderStatus';badge.className='badge renderStatus';const mode=document.querySelector('header .badge');(mode||document.querySelector('header b'))?.after(badge)}const button=document.querySelector('#renderMp4Btn'),pack=document.querySelector('#bundleBtn'),state=await this.health();badge.classList.remove('ready','warn','offline');if(state.render_ready){badge.textContent='MP4 listo';badge.classList.add('ready');badge.title=`Render local activo · Python ${state.python||'?'} · FFmpeg + FFprobe detectados`;if(button){button.disabled=false;button.title='Renderizar MP4 final localmente'}}else if(state.ok){badge.textContent='MP4 requiere FFmpeg';badge.classList.add('warn');badge.title='Servidor local activo, pero falta FFmpeg/FFprobe';if(button){button.disabled=true;button.title='Instala FFmpeg gratis y reinicia Studio'}if(pack)pack.title='Exportar paquete para render posterior'}else{badge.textContent='MP4 local inactivo';badge.classList.add('offline');badge.title='Abre Studio con start_studio_windows.bat para habilitar el render directo';if(button){button.disabled=false;button.title='Haz clic para ver cómo activar el render local'}}}
}
window.ProfitMenteBundleEngine=ProfitMenteBundleEngine;
if(typeof document!=='undefined')window.addEventListener('DOMContentLoaded',()=>new ProfitMenteBundleEngine().showReadiness());
if(typeof module!=='undefined')module.exports={ProfitMenteBundleEngine};
